"""Independent finite pair-graph fixed points,map/factor and cross-behavior controls."""

ORIGINAL = 'fn original_normalize<T: Ord>(signatures: Vec<T>) -> Vec<usize> {\n    let mut ids = BTreeMap::new();\n    signatures\n        .into_iter()\n        .map(|signature| {\n            let fresh = ids.len();\n            *ids.entry(signature).or_insert(fresh)\n        })\n        .collect()\n}\nimpl FiniteMoore {\nfn original_initial_partition(&self) -> Vec<usize> {\n        original_normalize(self.reports.clone())\n    }\nfn original_refine(&self, partition: &[usize]) -> Vec<usize> {\n        original_normalize(\n            (0..self.state_count())\n                .map(|state| {\n                    let mut signature = vec![partition[state]];\n                    signature.extend(self.transitions[state].iter().map(|&next| partition[next]));\n                    signature\n                })\n                .collect(),\n        )\n    }\nfn original_is_report_congruence(&self, partition: &[usize]) -> bool {\n        if partition.len() != self.state_count() {\n            return false;\n        }\n        for s in 0..self.state_count() {\n            for t in 0..s {\n                if partition[s] == partition[t]\n                    && (self.reports[s] != self.reports[t]\n                        || (0..self.input_count).any(|i| {\n                            partition[self.transitions[s][i]] != partition[self.transitions[t][i]]\n                        }))\n                {\n                    return false;\n                }\n            }\n        }\n        true\n    }\nfn original_behavioral_quotient(&self) -> MooreQuotient {\n        let mut partitions = vec![self.original_initial_partition()];\n        loop {\n            let next = self.original_refine(partitions.last().unwrap());\n            if next == *partitions.last().unwrap() {\n                break;\n            }\n            partitions.push(next);\n        }\n        let state_to_block = partitions.last().unwrap().clone();\n        let count = state_to_block.iter().copied().max().unwrap() + 1;\n        let mut representatives = vec![None; count];\n        for (state, &block) in state_to_block.iter().enumerate() {\n            if representatives[block].is_none() {\n                representatives[block] = Some(state);\n            }\n        }\n        let representatives: Vec<_> = representatives.into_iter().map(Option::unwrap).collect();\n        let quotient = Self::new(\n            representatives.iter().map(|&s| self.reports[s]).collect(),\n            representatives\n                .iter()\n                .map(|&s| {\n                    self.transitions[s]\n                        .iter()\n                        .map(|&t| state_to_block[t])\n                        .collect()\n                })\n                .collect(),\n            self.input_count,\n        )\n        .expect("stable partition defines a total quotient");\n        MooreQuotient {\n            partitions,\n            state_to_block,\n            quotient,\n        }\n    }\nfn original_factor_surjective_quotient(\n        &self,\n        target: &Self,\n        map: &[usize],\n    ) -> Result<Vec<usize>, MooreError> {\n        if self.input_count != target.input_count\n            || map.len() != self.state_count()\n            || map.iter().any(|&n| n >= target.state_count())\n            || map.iter().copied().collect::<BTreeSet<_>>().len() != target.state_count()\n        {\n            return Err(MooreError::InvalidQuotientMap);\n        }\n        for m in 0..self.state_count() {\n            if self.reports[m] != target.reports[map[m]]\n                || (0..self.input_count)\n                    .any(|i| map[self.transitions[m][i]] != target.transitions[map[m]][i])\n            {\n                return Err(MooreError::InvalidQuotientMap);\n            }\n        }\n        let minimal = self.original_behavioral_quotient();\n        let mut factor = vec![None; target.state_count()];\n        for m in 0..self.state_count() {\n            let block = minimal.state_to_block[m];\n            match factor[map[m]] {\n                Some(prior) if prior != block => return Err(MooreError::InvalidQuotientMap),\n                _ => factor[map[m]] = Some(block),\n            }\n        }\n        Ok(factor.into_iter().map(Option::unwrap).collect())\n    }\n}\n'

TESTS = r'''
fn machine(states:usize,inputs:usize,reports:usize,table:usize)->FiniteMoore{let labels=(0..states).map(|s|(reports>>s)&1).collect();let mut n=table;let mut rows=vec![vec![0;inputs];states];for row in &mut rows{for v in row{*v=n%states;n/=states;}}FiniteMoore::new(labels,rows,inputs).unwrap()}
fn bad_pairs(left:&FiniteMoore,right:&FiniteMoore)->Vec<bool>{assert_eq!(left.input_count,right.input_count);let n=left.state_count();let m=right.state_count();let mut bad:Vec<_>=(0..n*m).map(|v|left.reports[v/m]!=right.reports[v%m]).collect();for _ in 0..n*m{let old=bad.clone();for v in 0..n*m{for a in 0..left.input_count{bad[v]|=old[left.transitions[v/m][a]*m+right.transitions[v%m][a]];}}if old==bad{break;}}bad}
fn oracle_classes(m:&FiniteMoore)->Vec<usize>{let bad=bad_pairs(m,m);let n=m.state_count();let mut roots:Vec<usize>=Vec::new();(0..n).map(|s|{if let Some(k)=roots.iter().position(|&r|!bad[s*n+r]){k}else{roots.push(s);roots.len()-1}}).collect()}
fn stable(m:&FiniteMoore,p:&[usize])->bool{if p.len()!=m.state_count(){return false;}for s in 0..p.len(){for t in 0..p.len(){if p[s]==p[t]{if m.reports[s]!=m.reports[t]{return false;}for a in 0..m.input_count{if p[m.transitions[s][a]]!=p[m.transitions[t][a]]{return false;}}}}}true}
#[test]fn all_three_state_two_input_quotients_and_sparse_congruences(){
 let mut cases=0;for reports in 0..8{for table in 0..729{let m=machine(3,2,reports,table);let expected=oracle_classes(&m);let q=m.behavioral_quotient();assert_eq!(q.state_to_block,expected);assert_eq!(q,m.original_behavioral_quotient());assert!(m.verify_quotient(&q));assert!(m.is_report_congruence(&expected));let mut sparse=expected.clone();for id in &mut sparse{if *id==0{*id=usize::MAX;}}assert!(m.is_report_congruence(&sparse));
  for code in 0..27{let p=vec![code%3,(code/3)%3,(code/9)%3];assert_eq!(m.is_report_congruence(&p),stable(&m,&p));assert_eq!(m.is_report_congruence(&p),m.original_is_report_congruence(&p));}
  let count=expected.iter().max().unwrap()+1;assert_eq!(q.quotient.state_count(),count);for block in 0..count{let root=expected.iter().position(|&b|b==block).unwrap();assert_eq!(q.quotient.reports[block],m.reports[root]);for a in 0..2{assert_eq!(q.quotient.transitions[block][a],expected[m.transitions[root][a]]);}}
  let mut bad=q.clone();bad.state_to_block[0]=usize::MAX;assert!(!m.verify_quotient(&bad));let mut bad=q.clone();bad.partitions.clear();assert!(!m.verify_quotient(&bad));let mut bad=q.clone();bad.partitions.insert(0,q.partitions[0].clone());assert!(!m.verify_quotient(&bad));let mut bad=q;let mut labels=bad.quotient.reports.clone();labels[0]=7;bad.quotient=FiniteMoore::new(labels,bad.quotient.transitions.clone(),2).unwrap();assert!(!m.verify_quotient(&bad));cases+=1;
 }}assert_eq!(cases,5832);
}
#[test]fn every_small_surjective_map_and_cross_behavior_set(){
 let machines:Vec<_>=(0..4).flat_map(|r|(0..16).map(move|t|machine(2,2,r,t))).collect();let mut cases=0;
 for left in &machines{for right in &machines{let bad=bad_pairs(left,right);let same=(0..2).all(|s|(0..2).any(|t|!bad[s*2+t]))&&(0..2).all(|t|(0..2).any(|s|!bad[s*2+t]));assert_eq!(left.same_behavior_set(right),same);
  for code in 0..4{let map=[code%2,code/2];let surjective=map[0]!=map[1];let preserves=(0..2).all(|s|left.reports[s]==right.reports[map[s]]&&(0..2).all(|a|map[left.transitions[s][a]]==right.transitions[map[s]][a]));let actual=left.factor_surjective_quotient(right,&map);if surjective&&preserves{let classes=oracle_classes(left);let factor:Vec<_>=(0..2).map(|t|classes[map.iter().position(|&x|x==t).unwrap()]).collect();assert_eq!(actual,Ok(factor));}else{assert_eq!(actual,Err(MooreError::InvalidQuotientMap));}assert_eq!(actual,left.original_factor_surjective_quotient(right,&map));cases+=1;}
 }}assert_eq!(cases,16384);
 let left=FiniteMoore::new(vec![0,0,1],vec![vec![2],vec![2],vec![2]],1).unwrap();let right=FiniteMoore::new(vec![0,1],vec![vec![1],vec![1]],1).unwrap();assert_eq!(left.factor_surjective_quotient(&right,&[0,0,1]),Ok(vec![0,1]));assert!(left.same_behavior_set(&right));assert_eq!(left.factor_surjective_quotient(&right,&[]),Err(MooreError::InvalidQuotientMap));assert_eq!(left.factor_surjective_quotient(&right,&[0,0,2]),Err(MooreError::InvalidQuotientMap));
 assert_eq!(left.factor_surjective_quotient(&right,&[0,0,1,0]),Err(MooreError::InvalidQuotientMap));assert_eq!(left.factor_surjective_quotient(&right,&[0,1]),Err(MooreError::InvalidQuotientMap));
 assert_eq!(left.factor_surjective_quotient(&right,&[2,2,0]),Err(MooreError::InvalidQuotientMap),"range guard isolated before any observation rejection");
 let other=FiniteMoore::new(vec![0],vec![vec![]],0).unwrap();assert_eq!(left.factor_surjective_quotient(&other,&[0,0,0]),Err(MooreError::InvalidQuotientMap));assert!(!left.same_behavior_set(&other));
}
#[test]fn normalization_empty_alphabet_admission_and_refinement_chain(){
 assert_eq!(normalize([9,9,usize::MAX,7,usize::MAX]),vec![0,0,1,2,1]);let mut ids=BTreeMap::new();let signature=vec![usize::MAX,2,0];assert_eq!(intern_signature(&mut ids,&signature),0);assert_eq!(intern_signature(&mut ids,&signature),0);assert_eq!(ids.len(),1);assert_eq!(intern_signature(&mut ids,&[1,2,0]),1);assert_eq!(ids.len(),2);
 assert_eq!(FiniteMoore::new(Vec::new(),vec![vec![99]],1),Err(MooreError::EmptyCarrier));assert_eq!(FiniteMoore::new(vec![0,1],vec![vec![99]],1),Err(MooreError::TransitionShape));assert_eq!(FiniteMoore::new(vec![0],vec![vec![1]],1),Err(MooreError::TransitionOutsideCarrier));
 let m=FiniteMoore::new(vec![usize::MAX,0,usize::MAX],vec![vec![],vec![],vec![]],0).unwrap();assert_eq!(m.reports(),[usize::MAX,0,usize::MAX]);assert_eq!(m.transitions(),[vec![],vec![],vec![]]);assert_eq!(m.input_count(),0);assert_eq!(m.state_count(),3);assert_eq!(m.behavioral_quotient().state_to_block,vec![0,1,0]);assert!(!m.is_report_congruence(&[]));assert!(!m.is_report_congruence(&[0,0]));assert!(!m.is_report_congruence(&[0,0,0,0]));let wrong=FiniteMoore::new(vec![0,0,0],vec![vec![],vec![],vec![]],0).unwrap();assert!(!m.same_behavior_set(&wrong));
 let m=FiniteMoore::new(vec![0,0,0,0,1,1],vec![vec![1],vec![2],vec![4],vec![4],vec![4],vec![5]],1).unwrap();let q=m.behavioral_quotient();assert_eq!(q.partitions,vec![vec![0,0,0,0,1,1],vec![0,0,1,1,2,2],vec![0,1,2,2,3,3]]);let mut skipped=q.clone();skipped.partitions.remove(1);assert!(!m.verify_quotient(&skipped));let mut truncated=q.clone();truncated.partitions.pop();assert!(!m.verify_quotient(&truncated));truncated.state_to_block=truncated.partitions.last().unwrap().clone();assert!(!m.verify_quotient(&truncated),"isolate stabilization even with matching submitted map/canonical quotient");let mut forged=q;forged.partitions[1].pop();assert!(!m.verify_quotient(&forged));
 let m=FiniteMoore::new(vec![7,7],vec![vec![0],vec![1]],1).unwrap();let forged=MooreQuotient{partitions:vec![vec![0,1]],state_to_block:vec![0,1],quotient:m.clone()};assert!(!m.verify_quotient(&forged));let mut forged=m.behavioral_quotient();forged.partitions=vec![vec![0,1]];forged.state_to_block=vec![0,1];assert!(!m.verify_quotient(&forged),"isolate origin guard with canonical quotient unchanged");
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_moore_tests{use super::*;\n'+ORIGINAL+TESTS+'\n}\n'
